-- Switzerland: ES/DE/FR milestone translations, from the scaffolder's
-- drafts/ stub, translated and moved into the numbered sequence.

-- ---- es ----
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES
 ('ch-fedcouncil-einvoicing-decision', 'es', 'El Consejo Federal decide obligar a los proveedores del Estado a facturar electrónicamente', 'El Consejo Federal resolvió exigir a los proveedores de la administración federal la presentación de facturas electrónicas cuando el valor del contrato supere los 5.000 francos, con efecto desde el 1 de enero de 2016. El umbral se fijó para no cargar a los proveedores más pequeños.',
  '["Antecedente de la obligación de 2016, no un deber en sí mismo"]'),
 ('ch-b2g-supplier-duty', 'es', 'Los proveedores de la administración federal central deben facturar electrónicamente por encima de 5.000 CHF', 'La obligación entra en vigor. Vincula al proveedor a emitir, no al organismo a recibir, y el texto vinculante es la cláusula 9.4 de las condiciones generales de contratación de la Confederación, no un reglamento de la Compilación Sistemática. El umbral es de 5.000 francos sin IVA, matiz que solo recogen esas condiciones. Cantones, municipios y el ámbito de las EPF quedan fuera.',
  '["Compruebe si su contraparte es una unidad federal central: la lista publicada lo decide", "Por debajo de 5.000 CHF sin IVA, el papel sigue permitido"]'),
 ('ch-pdf-counts-as-electronic', 'es', 'La Confederación confirma que un PDF enviado por correo satisface la obligación', 'Al informar de que la cuota de factura electrónica se había cuadruplicado hasta cerca del 60 %, la Administración Federal de Finanzas confirmó que la administración federal acepta también facturas en PDF enviadas por correo electrónico. El deber es facturar sin papel, no facturar en formato estructurado: el dato más determinante de este país para dimensionar una integración.',
  '["No dimensione una cadena estructurada solo por la fecha de 2016"]'),
 ('ch-vat-filing-online-mandatory', 'es', 'La declaración electrónica del IVA pasa a ser obligatoria para toda empresa registrada', 'El artículo 65a de la Ley del IVA, introducido por la revisión parcial vigente desde el 1 de enero de 2024 con un año de transición, convierte la presentación en línea por el portal de la Administración Federal de Contribuciones en la única vía. Es un canal de presentación y no un régimen de declaración: se envían totales periódicos agregados y ningún dato de factura u operación llega a la administración.',
  '["Regístrese en el portal de la ESTV si declara el IVA suizo", "No lo interprete como e-reporting: no se transmite dato alguno de operaciones"]'),
 ('ch-zurich-digital-standard-2027', 'es', 'El cantón de Zúrich hace de la entrega digital de facturas su estándar desde 2027', 'El gobierno cantonal declaró la entrega digital el estándar a partir de 2027, quedando el papel como excepción. Se invita a los proveedores, no se les obliga; no se fija umbral ni se prescribe formato. La obligación federal no alcanza a los cantones, de modo que esto es la frontera actual de la práctica cantonal y no un nuevo deber.',
  '["Siga la práctica cantonal aparte de la regla federal: son regímenes distintos"]');

-- ---- de ----
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES
 ('ch-fedcouncil-einvoicing-decision', 'de', 'Der Bundesrat beschliesst, Lieferanten des Bundes zur elektronischen Rechnungsstellung zu verpflichten', 'Der Bundesrat beschloss, Lieferanten der Bundesverwaltung zur Einreichung elektronischer Rechnungen zu verpflichten, sofern der Vertragswert 5''000 Franken übersteigt, mit Wirkung ab 1. Januar 2016. Die Schwelle wurde gesetzt, um kleinere Lieferanten zu schonen.',
  '["Hintergrund zur Pflicht von 2016, nicht selbst eine Pflicht"]'),
 ('ch-b2g-supplier-duty', 'de', 'Lieferanten der zentralen Bundesverwaltung müssen über 5''000 CHF elektronisch fakturieren', 'Die Pflicht tritt in Kraft. Sie bindet den Lieferanten zum Ausstellen, nicht die Behörde zum Empfangen, und der verbindliche Text ist Ziffer 9.4 der AGB des Bundes und keine Verordnung der Systematischen Sammlung. Die Schwelle beträgt 5''000 Franken exklusive MWST, ein Zusatz, den nur die AGB nennen. Kantone, Gemeinden und der ETH-Bereich liegen ausserhalb.',
  '["Prüfen, ob Ihre Gegenpartei eine zentrale Bundeseinheit ist -- die veröffentlichte Liste entscheidet", "Unter 5''000 CHF exkl. MWST bleibt Papier zulässig"]'),
 ('ch-pdf-counts-as-electronic', 'de', 'Der Bund bestätigt, dass ein per E-Mail gesandtes PDF die Pflicht erfüllt', 'Bei der Meldung, der E-Rechnungs-Anteil habe sich auf rund 60 Prozent vervierfacht, bestätigte die Eidgenössische Finanzverwaltung, dass die Bundesverwaltung auch per E-Mail gesandte PDF-Rechnungen akzeptiert. Die Pflicht lautet, ohne Papier zu fakturieren, nicht strukturiert zu fakturieren -- die folgenreichste Tatsache dieses Landes für jede Integrationsplanung.',
  '["Keine strukturierte Strecke allein aufgrund des Datums 2016 planen"]'),
 ('ch-vat-filing-online-mandatory', 'de', 'Die elektronische MWST-Abrechnung wird für jedes registrierte Unternehmen verbindlich', 'Artikel 65a MWSTG, eingeführt durch die Teilrevision mit Inkrafttreten am 1. Januar 2024 und einem Übergangsjahr, macht die Online-Einreichung über das Portal der Eidgenössischen Steuerverwaltung zum einzigen Weg. Das ist ein Einreichungskanal und kein Meldeverfahren: übermittelt werden periodische Summen, keine Rechnungs- oder Transaktionsdaten erreichen die Verwaltung.',
  '["Für das ESTV-Portal registrieren, wenn Sie Schweizer MWST abrechnen", "Nicht als E-Reporting lesen -- es werden keine Transaktionsdaten übermittelt"]'),
 ('ch-zurich-digital-standard-2027', 'de', 'Der Kanton Zürich macht die digitale Rechnungszustellung ab 2027 zum Standard', 'Der Regierungsrat erklärte die digitale Zustellung ab 2027 zum Standard, Papier wird zur Ausnahme. Lieferanten werden aufgerufen, nicht verpflichtet; weder Schwelle noch Format sind vorgegeben. Die Bundespflicht erreicht die Kantone nicht, dies ist also die aktuelle Grenze kantonaler Praxis und keine neue Pflicht.',
  '["Kantonale Praxis getrennt von der Bundesregel verfolgen -- es sind verschiedene Regime"]');

-- ---- fr ----
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES
 ('ch-fedcouncil-einvoicing-decision', 'fr', 'Le Conseil fédéral décide d''obliger les fournisseurs de la Confédération à facturer par voie électronique', 'Le Conseil fédéral a décidé d''imposer aux fournisseurs de l''administration fédérale la remise de factures électroniques lorsque la valeur du contrat dépasse 5 000 francs, avec effet au 1er janvier 2016. Le seuil a été fixé pour épargner les plus petits fournisseurs.',
  '["Antécédent de l''obligation de 2016, non un devoir en soi"]'),
 ('ch-b2g-supplier-duty', 'fr', 'Les fournisseurs de l''administration fédérale centrale doivent facturer par voie électronique au-delà de 5 000 CHF', 'L''obligation entre en vigueur. Elle lie le fournisseur à émettre, non l''autorité à recevoir, et le texte contraignant est la clause 9.4 des conditions générales de la Confédération, non une ordonnance du Recueil systématique. Le seuil est de 5 000 francs hors TVA, précision que seules ces conditions apportent. Cantons, communes et domaine des EPF en sont exclus.',
  '["Vérifier si votre contrepartie est une unité fédérale centrale : la liste publiée en décide", "En dessous de 5 000 CHF hors TVA, le papier reste admis"]'),
 ('ch-pdf-counts-as-electronic', 'fr', 'La Confédération confirme qu''un PDF envoyé par courriel satisfait l''obligation', 'En annonçant que la part de factures électroniques avait quadruplé pour atteindre environ 60 %, l''Administration fédérale des finances a confirmé que l''administration accepte aussi les factures PDF envoyées par courriel. L''obligation est de facturer sans papier, non de facturer en format structuré : le fait le plus lourd de conséquences pour cadrer une intégration.',
  '["Ne pas dimensionner une chaîne structurée sur la seule foi de la date de 2016"]'),
 ('ch-vat-filing-online-mandatory', 'fr', 'La déclaration électronique de TVA devient obligatoire pour toute entreprise assujettie', 'L''article 65a de la loi TVA, introduit par la révision partielle en vigueur depuis le 1er janvier 2024 avec une année de transition, fait du dépôt en ligne via le portail de l''Administration fédérale des contributions la seule voie. C''est un canal de dépôt et non un régime déclaratif : des totaux périodiques sont transmis, aucune donnée de facture ou de transaction ne parvient à l''administration.',
  '["S''inscrire au portail de l''AFC si vous déclarez la TVA suisse", "Ne pas y voir de l''e-reporting : aucune donnée de transaction n''est transmise"]'),
 ('ch-zurich-digital-standard-2027', 'fr', 'Le canton de Zurich fait de la remise numérique des factures son standard dès 2027', 'Le gouvernement cantonal a déclaré la remise numérique standard à partir de 2027, le papier devenant l''exception. Les fournisseurs sont invités et non obligés ; aucun seuil n''est fixé ni aucun format prescrit. L''obligation fédérale n''atteint pas les cantons : c''est donc la frontière actuelle de la pratique cantonale, non un devoir nouveau.',
  '["Suivre la pratique cantonale séparément de la règle fédérale -- ce sont des régimes distincts"]');

-- ---- what this migration claims it did ----
